def drive(me, enemy, arena):
    if not me.can_drive:
        return (0, 0)
    mem = me.memory
    if "phase" not in mem:
        mem["phase"] = "spin"
        mem["timer"] = 0.0
        mem["last_time"] = arena.time
    dt = arena.time - mem["last_time"]
    if dt < 0.0 or dt > 1.0:
        dt = 0.05
    mem["last_time"] = arena.time
    mem["timer"] = mem.get("timer", 0.0) + dt

    rpm = 0.0
    if "front" in me.weapons:
        rpm = me.weapons["front"]["rpm"]
        if rpm < 0.0:
            rpm = -rpm

    if mem["phase"] == "spin":
        if rpm > 1800.0:
            mem["phase"] = "attack"
            mem["timer"] = 0.0
    elif mem["phase"] == "attack":
        dx = enemy.x - me.x
        dy = enemy.y - me.y
        dist = hypot(dx, dy)
        if dist < 2.4:
            eh = radians(enemy.heading)
            ex = me.x - enemy.x
            ey = me.y - enemy.y
            dot = ex * cos(eh) + ey * sin(eh)
            if dot > 0.0:
                mem["phase"] = "retreat"
                mem["timer"] = 0.0
    elif mem["phase"] == "retreat":
        if mem["timer"] > 0.7:
            mem["phase"] = "attack"
            mem["timer"] = 0.0

    tx = 0.0
    ty = 0.0
    if mem["phase"] == "spin":
        dx = me.x - enemy.x
        dy = me.y - enemy.y
        d = hypot(dx, dy)
        if d < 4.0 and d > 0.1:
            tx = me.x + dx / d * 2.0
            ty = me.y + dy / d * 2.0
        else:
            tx = 0.0
            ty = 0.0
    elif mem["phase"] == "retreat":
        dx = me.x - enemy.x
        dy = me.y - enemy.y
        d = hypot(dx, dy)
        if d > 0.1:
            tx = me.x + dx / d * 2.0
            ty = me.y + dy / d * 2.0
        else:
            tx = 0.0
            ty = 0.0
    else:
        eh = radians(enemy.heading)
        ex = me.x - enemy.x
        ey = me.y - enemy.y
        dot = ex * cos(eh) + ey * sin(eh)
        if dot > 0.0:
            tx = enemy.x - cos(eh) * 0.8
            ty = enemy.y - sin(eh) * 0.8
        else:
            tx = enemy.x
            ty = enemy.y

    if hypot(me.x, me.y) > arena.radius - 1.2:
        tx = 0.0
        ty = 0.0
    r = hypot(tx, ty)
    maxr = arena.radius - 1.0
    if r > maxr:
        tx = tx / r * maxr
        ty = ty / r * maxr

    b = bearing_to(tx, ty)
    if abs(b) > 90.0:
        base = 0.0
        if b > 0.0:
            turn = 1.0
        else:
            turn = -1.0
    else:
        base = 1.0
        turn = b / 45.0
        if turn > 1.0:
            turn = 1.0
        elif turn < -1.0:
            turn = -1.0
    left = base - turn
    right = base + turn
    if left > 1.0:
        left = 1.0
    elif left < -1.0:
        left = -1.0
    if right > 1.0:
        right = 1.0
    elif right < -1.0:
        right = -1.0
    return (left, right)

